questionvariables.text:
/* Randomisation of (a) */
numTwoDP:rand_with_prohib(101,999,[200,300,400,500,600,700,800,900])/100;
numOneDP:rand_with_prohib(11,99,[20,30,40,50,60,70,80,90])/10;
numZeroDP:rand(9)+1;
aList:random_permutation([numZeroDP,numOneDP,numTwoDP]);

simp:false;
tans1: ev(float((first(aList)*10^4 + second(aList)*10^3 + third(aList)*10^5)/10^(floor(log(first(aList)*10^4 + second(aList)*10^3 + third(aList)*10^5)/log(10)))),simp)*10^ev(floor(log(first(aList)*10^4 + second(aList)*10^3 + third(aList)*10^5)/log(10)),simp);
simp:true;

/* Randomisation of (b) */
bList:rand_selection([-4,-3,-2,-1,2,3,4,5],3);

simp:false;
tans2:10^ev(first(bList)+second(bList)+third(bList),simp);
simp:true;

/* Randomisation of (c) */
cUnitsList:rand_selection(["seconds","minutes","hours"],2);

ratioDec:rand_with_prohib(11,79,[20,30,40,50,60,70])/10;
ratioPow:rand(8)+2;

cTimeShortHrs:rand_with_prohib(11,99,[20,30,40,50,60,70,80,90])*10^(rand(2)+1);
cTimeShortCorrUnit: if second(cUnitsList)="seconds" then cTimeShortHrs*3600 else if second(cUnitsList)="minutes" then cTimeShortHrs*60 else cTimeShortHrs;

cTimeShortPow:floor(log(cTimeShortCorrUnit)/log(10))-1;
cTimeShortDec:cTimeShortCorrUnit/(10^cTimeShortPow);

cTimeLongHrs:cTimeShortHrs*(ratioDec*10^ratioPow);
cTimeLongCorrUnit: if first(cUnitsList)="seconds" then cTimeLongHrs*3600 else if first(cUnitsList)="minutes" then cTimeLongHrs*60 else cTimeLongHrs;

cTimeLongPow:floor(log(cTimeLongCorrUnit)/log(10))+1;
cTimeLongDec:cTimeLongCorrUnit/(10^cTimeLongPow);

simp:false;
tans3: float(ratioDec)*10^ratioPow;
simp:true;

/* Randomisation of (d) */

dUnitsList:rand_selection(["m", "m", "cm", "cm", "mm", "mm"],3);

dLengthM:(rand(9)+11)/10;
dLengthCorrUnit: if first(dUnitsList)="mm" then dLengthM*1000 else if first(dUnitsList)="cm" then dLengthM*100 else dLengthM;

dLengthPow:rand([2,3]);
dLengthDec:dLengthCorrUnit/(10^dLengthPow);

dWidthM:rand_with_prohib(51,99,[60,70,80,90])/10;
dWidthCorrUnit: if second(dUnitsList)="mm" then dWidthM*1000 else if second(dUnitsList)="cm" then dWidthM*100 else dWidthM;

dHeightM:rand_with_prohib(11,49,[20,30,40])/10;
dHeightCorrUnit: if third(dUnitsList)="mm" then dHeightM*1000 else if third(dUnitsList)="cm" then dHeightM*100 else dHeightM;

dHeightPow:rand([-1,-2]);
dHeightDec:dHeightCorrUnit/(10^dHeightPow);

dVol:dLengthM*dWidthM*dHeightM*1000000;
dVolPow:floor(log(dVol)/log(10));

simp:false;
tans4: ev(float(dVol/10^dVolPow),simp)*10^dVolPow;

feedbackvariables.text:
/* Node 1: Check correct answer */
/* Node 2: Worked solution */
/* Node 3: Check correct answer, but wrong standard form */

/* Node 1: Check correct answer */
/* Node 2: Worked solution */
/* Node 3: Correct answer, incorrect form */
/* Node 4: Multiply powers instead of adding */
node4_error: 10^ev(first(bList)*second(bList)*third(bList),simp);

/* Node 1: Check correct answer */
/* Node 2: Worked solution */
/* Node 3: Check correct answer, but wrong standard form */
/* Node 4: Check no conversion of units */
node4_error: (cTimeLongDec*10^cTimeLongPow)/(cTimeShortDec*10^cTimeShortPow);

/* Node 1: Check correct answer */
/* Node 2: Worked solution */
/* Node 3: Correct answer, but wrong standard form (2) */

/* Node 4: Wrong units used but correct standard form (2) */
node4_test: if ans4=ev(float(dVol/10^dVolPow),simp)*10^ev(dVolPow+3,simp) or ans4=ev(float(dVol/10^dVolPow),simp)*10^ev(dVolPow-6,simp) then 1 else 0;

/* Node 5: Wrong units and wrong standard form (1) */
node5_test: if ev(ans4,simp)=ev(float(dVol/10^dVolPow)*10^(dVolPow+3),simp) or ev(ans4,simp)=ev(float(dVol/10^dVolPow)*10^(dVolPow-6),simp) then 1 else 0;
